import { AnimatePresence, motion } from 'framer-motion';
import { ArrowRight, Menu, X } from 'lucide-react';
import { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';

// ─── Design Tokens (Identical to Homepage System) ───────────────────────────
const C = {
  charcoal:    '#1C1917',   // primary button bg
  charcoalHov: '#292524',   // hover
  ivory:       '#FFFDFC',
  rose:        '#DDB7B0',
  gold:        '#D6BE8A',
  sage:        '#B8C4B2',
  plum:        '#3D2B38',
  mauve:       '#9B7A8A',
  surface:     'rgba(255,253,252,0.72)',
  border:      'rgba(221,183,176,0.18)',
};

// ─── SVG Logo Component ──────────────────────────────────────────────────────
const Logo = () => (
  <svg width="44" height="44" viewBox="0 0 44 44" fill="none" xmlns="http://www.w3.org/2000/svg">
    <defs>
      <radialGradient id="glow" cx="50%" cy="50%" r="50%">
        <stop offset="0%" stopColor={C.gold} stopOpacity="0.4" />
        <stop offset="100%" stopColor={C.rose} stopOpacity="0" />
      </radialGradient>
    </defs>
    <circle cx="22" cy="22" r="21" fill="url(#glow)" />
    {/* Heart Framework */}
    <path d="M22 32 C22 32 10 24 10 17 C10 13.5 12.5 11 16 11 C18.5 11 20.5 12.5 22 14.5 C23.5 12.5 25.5 11 28 11 C31.5 11 34 13.5 34 17 C34 24 22 32 22 32Z"
      fill="none" stroke={C.rose} strokeWidth="1.2" strokeLinejoin="round" />
    {/* Keyhole Anchor */}
    <circle cx="22" cy="20" r="3" fill="none" stroke={C.gold} strokeWidth="1.1" />
    <rect x="20.5" y="22.5" width="3" height="4" rx="1" fill="none" stroke={C.gold} strokeWidth="1.1" />
    {/* Feathered Wings */}
    <path d="M10 20 Q6 17 8 13 Q12 15 12 20" fill="none" stroke={C.sage} strokeWidth="1" strokeLinecap="round" />
    <path d="M34 20 Q38 17 36 13 Q32 15 32 20" fill="none" stroke={C.sage} strokeWidth="1" strokeLinecap="round" />
    {/* Accent Details */}
    <path d="M8 13 Q10 11 12 13" fill="none" stroke={C.sage} strokeWidth="0.8" strokeLinecap="round" />
    <path d="M36 13 Q34 11 32 13" fill="none" stroke={C.sage} strokeWidth="0.8" strokeLinecap="round" />
  </svg>
);

const navLinks = [
  { label: 'Home', path: '/' },
  { label: 'About', path: '/about' },
  { label: 'Services', path: '/services' },
  { label: 'Blog', path: '/blog' },
  { label: 'Contact', path: '/contact' },
];

// ─── Navbar Component ────────────────────────────────────────────────────────
const Navbar = ({ scrolled }) => {
  const [open, setOpen] = useState(false);
  const location = useLocation();

  return (
    <motion.nav
      initial={{ y: -60, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      transition={{ duration: 0.8, ease: 'easeOut' }}
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        zIndex: 100,
        padding: '0 2rem',
        height: '72px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        background: scrolled ? 'rgba(255,253,252,0.92)' : 'transparent',
        backdropFilter: scrolled ? 'blur(20px)' : 'none',
        borderBottom: scrolled ? `1px solid ${C.border}` : 'none',
        transition: 'all 0.4s ease',
      }}
    >
      {/* Brand Identity Branding */}
      <Link to="/" style={{ display: 'flex', alignItems: 'center', gap: '10px', textDecoration: 'none' }}>
        <Logo />
        <div>
          <div style={{ fontFamily: 'Cormorant Garamond, serif', fontSize: '1.25rem', fontWeight: 600, color: C.plum, lineHeight: 1 }}>
            Struvive
          </div>
          <div style={{ fontFamily: 'Manrope, sans-serif', fontSize: '0.62rem', letterSpacing: '0.18em', color: C.sage, textTransform: 'uppercase', marginTop: '1px', fontWeight: 600 }}>
            Emolings
          </div>
        </div>
      </Link>

      {/* Desktop Navigation Link Cluster */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '2.2rem' }} className="desktop-nav">
        {navLinks.map(link => {
          const isActive = location.pathname === link.path;
          return (
            <Link
              key={link.path}
              to={link.path}
              style={{
                fontFamily: 'Manrope, sans-serif',
                fontSize: '0.85rem',
                fontWeight: isActive ? 600 : 500,
                color: isActive ? C.rose : C.plum,
                letterSpacing: '0.04em',
                textDecoration: 'none',
                transition: 'color 0.2s ease',
                position: 'relative',
                paddingBottom: '2px',
              }}
            >
              {link.label}
              {isActive && (
                <motion.div
                  layoutId="underline"
                  style={{ position: 'absolute', bottom: -2, left: 0, right: 0, height: '1px', background: C.rose }}
                />
              )}
            </Link>
          );
        })}

        {/* Core Charcoal Call-to-Action Primitive */}
        <Link to="/book" style={{ textDecoration: 'none' }}>
          <motion.button
            whileHover={{ scale: 1.03, backgroundColor: C.charcoalHov }}
            whileTap={{ scale: 0.97 }}
            style={{
              background: C.charcoal,
              color: C.ivory,
              border: 'none',
              borderRadius: '6px',
              padding: '10px 24px',
              fontFamily: 'Manrope, sans-serif',
              fontSize: '0.82rem',
              fontWeight: 600,
              letterSpacing: '0.03em',
              cursor: 'pointer',
              transition: 'background 0.2s',
              display: 'inline-flex',
              alignItems: 'center',
              gap: '6px',
            }}
          >
            Book Session <ArrowRight size={13} />
          </motion.button>
        </Link>
      </div>

      {/* Mobile Interaction Toggle Trigger */}
      <button
        onClick={() => setOpen(!open)}
        style={{ display: 'none', background: 'none', border: 'none', color: C.plum, cursor: 'pointer' }}
        className="mobile-menu-btn"
      >
        {open ? <X size={22} /> : <Menu size={22} />}
      </button>

      {/* Mobile Navigation Dropdown Drawer */}
      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            transition={{ duration: 0.3, ease: 'easeInOut' }}
            style={{
              position: 'absolute',
              top: '72px',
              left: 0,
              right: 0,
              background: 'rgba(255,253,252,0.98)',
              backdropFilter: 'blur(20px)',
              padding: '1.5rem 2rem 2rem',
              borderBottom: `1px solid ${C.border}`,
              display: 'flex',
              flexDirection: 'column',
              gap: '1.2rem',
            }}
          >
            {navLinks.map(link => (
              <Link
                key={link.path}
                to={link.path}
                onClick={() => setOpen(false)}
                style={{
                  fontFamily: 'Manrope, sans-serif',
                  fontSize: '1rem',
                  fontWeight: location.pathname === link.path ? 600 : 500,
                  color: location.pathname === link.path ? C.rose : C.plum,
                  textDecoration: 'none',
                }}
              >
                {link.label}
              </Link>
            ))}

            <Link to="/book" onClick={() => setOpen(false)} style={{ textDecoration: 'none' }}>
              <button style={{
                background: C.charcoal,
                color: C.ivory,
                border: 'none',
                borderRadius: '6px',
                padding: '12px 28px',
                fontFamily: 'Manrope, sans-serif',
                fontSize: '0.9rem',
                fontWeight: 600,
                letterSpacing: '0.03em',
                cursor: 'pointer',
                width: '100%',
                display: 'inline-flex',
                alignItems: 'center',
                justifyContent: 'center',
                gap: '8px',
              }}>
                Book a Session <ArrowRight size={14} />
              </button>
            </Link>
          </motion.div>
        )}
      </AnimatePresence>

      <style>{`
        @media (max-width: 768px) {
          .desktop-nav { display: none !important; }
          .mobile-menu-btn { display: block !important; }
        }
      `}</style>
    </motion.nav>
  );
};

export default Navbar;
